import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MinimalistBlurListProps = Record<string, any>;

const MinimalistBlurList: React.FC<MinimalistBlurListProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "Strategic Roadmap",
  titleSize = 80,
  titleColor = "#000000",
  textItem1 = "Visionary Concept",
  textItem2 = "Strategic Planning",
  textItem3 = "Design Iteration",
  textItem4 = "Development Phase",
  textItem5 = "Global Launch",
  textColor = "#1a1a1a",
  staggerDelay = 0.8,
  initialBlurStrength = 20,
  fontSize = 60,
  lineSpacing = 40,
}) => {
  // Load Fonts
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  const items = [textItem1, textItem2, textItem3, textItem4, textItem5];

  // Title Animation
  const titleDuration = 1.5 * fps;
  const titleProgress = interpolate(
    frame,
    [0, titleDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );
  
  const titleBlur = interpolate(titleProgress, [0, 1], [initialBlurStrength, 0]);
  // Title is also blurred from the beginning (visible)
  const titleOpacity = 1; 

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: lineSpacing,
          width: width * 0.8, // Responsive width
          justifyContent: "center",
          alignItems: "flex-start", // Align text to left
        }}
      >
        {/* Title Element */}
        <h1
          style={{
            fontSize: titleSize,
            fontWeight: 700,
            color: titleColor,
            textAlign: "left",
            margin: 0,
            marginBottom: lineSpacing * 1.5, // Extra spacing below title
            filter: `blur(${titleBlur}px)`,
            opacity: titleOpacity,
            willChange: "filter",
            lineHeight: 1.1,
          }}
        >
          {titleText}
        </h1>

        {items.map((item, index) => {
          // Calculate start frame for each item based on stagger
          // Adding a small delay after title starts
          const startFrame = (index * (staggerDelay * fps)) + (0.5 * fps);
          
          // Animation duration for the reveal itself
          const revealDuration = 1.5 * fps; 

          // Interpolate progress (0 to 1)
          const progress = interpolate(
            frame,
            [startFrame, startFrame + revealDuration],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }
          );

          // Map progress to visual properties
          const blurRadius = interpolate(progress, [0, 1], [initialBlurStrength, 0]);
          
          // Updated: Opacity is constant 1 so they are "blurred from the beginning"
          const opacity = 1; 
          
          // Updated: Removed translateY so they don't "appear" by sliding up
          const translateY = 0; 

          return (
            <div
              key={index}
              style={{
                fontSize: fontSize,
                fontWeight: 600,
                color: textColor,
                textAlign: "left",
                filter: `blur(${blurRadius}px)`,
                opacity: opacity,
                transform: `translateY(${translateY}px)`,
                willChange: "filter", // Removed opacity/transform from willChange as they are static
                lineHeight: 1.2,
              }}
            >
              {item}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default MinimalistBlurList;